+import parseLinkHeader from './core/parse-link-header.js';
+
+const unquote = (value: string): string => {
+	if (value.length >= 2 && value.startsWith('"') && value.endsWith('"')) {
+		return value.slice(1, -1);
+	}
+
+	return value;
+};
+
+/**
+Get the absolute URL of the first `Link` header entry whose `rel` includes the given relation.
+
+@param header - The raw `Link` header value.
+@param currentUrl - The URL the header was received from, used to resolve relative targets.
+@param relation - The relation type to look for, for example `next`.
+@returns The absolute target URL, or `null` when no entry has the relation.
+@throws When the header is not empty and is not valid `Link` header syntax.
+*/
+// eslint-disable-next-line @typescript-eslint/ban-types
+export function paginationTarget(header: string | undefined, currentUrl: string | URL, relation: string): string | null {
+	if (header === undefined || header.trim() === '') {
+		return null;
+	}
+
+	const wanted = relation.toLowerCase();
+
+	for (const {reference, parameters} of parseLinkHeader(header)) {
+		const relationName = Object.keys(parameters).find(name => name.toLowerCase() === 'rel');
+		if (relationName === undefined) {
+			continue;
+		}
+
+		const relations = unquote(parameters[relationName]!).toLowerCase().split(/\s+/);
+		if (relations.includes(wanted)) {
+			return new URL(reference, currentUrl).href;
+		}
+	}
+
+	return null;
+}
diff --git a/test/pagination-target.ts b/test/pagination-target.ts
new file mode 100644
index 0000000..4960978
--- /dev/null
+++ b/test/pagination-target.ts
@@ -0,0 +1,50 @@
+import test from 'ava';
+import {paginationTarget} from '../source/pagination-target.js';
+
+const currentUrl = 'https://example.com/items?page=1';
+
+test('returns the target of a quoted relation', t => {
+	t.is(paginationTarget('<https://example.com/items?page=2>; rel="next"', currentUrl, 'next'), 'https://example.com/items?page=2');
+});
+
+test('returns the target of an unquoted relation', t => {
+	t.is(paginationTarget('<https://example.com/items?page=2>; rel=next', currentUrl, 'next'), 'https://example.com/items?page=2');
+});
+
+test('matches one of several whitespace-separated relations', t => {
+	t.is(paginationTarget('<https://example.com/items?page=9>; rel="last  next"', currentUrl, 'next'), 'https://example.com/items?page=9');
+	t.is(paginationTarget('<https://example.com/items?page=9>; rel="last next"', currentUrl, 'last'), 'https://example.com/items?page=9');
+});
+
+test('does not match a relation by substring', t => {
+	t.is(paginationTarget('<https://example.com/items?page=2>; rel="nextpage"', currentUrl, 'next'), null);
+});
+
+test('returns the first matching entry', t => {
+	const header = '<https://example.com/items?page=0>; rel="prev", <https://example.com/items?page=2>; rel="next", <https://example.com/items?page=3>; rel="next"';
+	t.is(paginationTarget(header, currentUrl, 'next'), 'https://example.com/items?page=2');
+	t.is(paginationTarget(header, currentUrl, 'prev'), 'https://example.com/items?page=0');
+});
+
+test('resolves relative targets against the current URL', t => {
+	t.is(paginationTarget('</items?page=2>; rel="next"', currentUrl, 'next'), 'https://example.com/items?page=2');
+	t.is(paginationTarget('<?page=2>; rel="next"', new URL(currentUrl), 'next'), 'https://example.com/items?page=2');
+});
+
+test('returns null when the relation is absent', t => {
+	t.is(paginationTarget('<https://example.com/items?page=0>; rel="prev"', currentUrl, 'next'), null);
+	t.is(paginationTarget('<https://example.com/items?page=0>; title="next"', currentUrl, 'next'), null);
+});
+
+test('returns null for absent or whitespace-only headers', t => {
+	t.is(paginationTarget(undefined, currentUrl, 'next'), null);
+	t.is(paginationTarget('', currentUrl, 'next'), null);
+	t.is(paginationTarget(' \t ', currentUrl, 'next'), null);
+});
+
+test('throws on malformed headers', t => {
+	t.throws(() => paginationTarget('https://example.com/items?page=2; rel="next"', currentUrl, 'next'));
+	t.throws(() => paginationTarget('<https://example.com/items?page=2>', currentUrl, 'next'));
+	t.throws(() => paginationTarget('<https://example.com/items?page=2>; rel', currentUrl, 'next'));
+	t.throws(() => paginationTarget('<https://example.com/items?page=2>; rel="next",', currentUrl, 'next'));
+});
